"""Match examples (messy location strings -> record_id) generated by fixed rules from the released
names, and a baseline matcher (normalised exact match plus admin context)."""
from __future__ import annotations

import hashlib
import re
import unicodedata
from collections import Counter, defaultdict

from .config import SPLIT_BUCKETS, SPLIT_SALT
from .textnorm import ar_core_key, ar_match_key, latin_match_key, script_issue, script_of, visible

TARGET_CLASSES = {"P", "A"}
MAX_TARGETS_PER_STATE = 1500
UNIQUE_SHARE = 0.10            # share of targets per state whose name no other record shares
MAX_DISTRACTORS = 10
GENERIC_AR = {"P": {"PPLX": "حي"}, "A": {}}
LATIN_GENERIC = {"district", "dist", "city", "governorate", "province", "village", "town", "region",
                 "area", "quarter", "municipality", "emirate", "wilayat", "state"}
SEP = re.compile(r"\s*[،,;|]\s*|\s+-\s+")


def _hx(*parts) -> int:
    return int(hashlib.sha256("|".join(str(p) for p in parts).encode("utf-8")).hexdigest()[:12], 16)


def split_of(place) -> str:
    """Hash of the admin1 unit (or the country when admin1 is unresolved): every example of one
    admin1 unit is in the same split."""
    a1 = None
    if len(place["admin_path"]) > 1 and place["admin_path"][1]["status"] == "resolved":
        a1 = place["admin_path"][1]["code"]
    b = _hx(SPLIT_SALT, place["country_code"], a1 or "unresolved") % 100
    acc = 0
    for name, share in SPLIT_BUCKETS:
        acc += share
        if b < acc:
            return name
    return SPLIT_BUCKETS[-1][0]


# --- orthographic and typo rules -----------------------------------------------------------

def _ortho_variants(s: str) -> list[tuple[str, str]]:
    """(rule, variant) pairs for an Arabic name; only variants that differ from s."""
    out = []
    words = s.split()
    if any(w.endswith("ة") for w in words):
        out.append(("taa_marbuta_to_heh", " ".join(w[:-1] + "ه" if w.endswith("ة") else w for w in words)))
    if re.search("[أإآ]", s):
        out.append(("hamza_alef_to_alef", re.sub("[أإآ]", "ا", s)))
    elif re.match("^ا", s) and not s.startswith("ال"):
        out.append(("alef_to_hamza_alef", "أ" + s[1:]))
    if any(w.endswith("ى") for w in words):
        out.append(("alef_maqsura_to_yeh", " ".join(w[:-1] + "ي" if w.endswith("ى") else w for w in words)))
    elif any(w.endswith("ي") and len(w) > 2 for w in words):
        out.append(("yeh_to_alef_maqsura", " ".join(w[:-1] + "ى" if w.endswith("ي") and len(w) > 2 else w for w in words)))
    if words and words[0].startswith("ال") and len(words[0]) >= 4:
        out.append(("drop_article", " ".join([words[0][2:]] + words[1:])))
    elif words and not words[0].startswith("ال") and len(words) == 1:
        out.append(("add_article", "ال" + s))
    if "ئ" in s or "ؤ" in s:
        out.append(("hamza_seat_fold", s.replace("ئ", "ي").replace("ؤ", "و")))
    if len(words) == 2 and words[0] in ("أبو", "ابو", "عبد", "بني", "بنى", "أم", "ام"):
        out.append(("join_compound", words[0] + words[1]))
    return [(r, v) for r, v in out if v != s]


def _typo(s: str, h: int) -> str | None:
    """One edit on an inner letter: delete it or swap it with the next letter."""
    letters = [i for i, ch in enumerate(s) if ch.isalpha()]
    if len(letters) < 5:
        return None
    inner = letters[1:-1]
    i = inner[h % len(inner)]
    if (h >> 8) % 2 == 0 or i + 1 >= len(s) or not s[i + 1].isalpha():
        t = s[:i] + s[i + 1:]
    else:
        t = s[:i] + s[i + 1] + s[i] + s[i + 2:]
    return t if t != s else None


def _latin_messy(s: str, h: int) -> tuple[str, str]:
    t = "".join(ch for ch in unicodedata.normalize("NFKD", s) if unicodedata.category(ch) != "Mn")
    t = re.sub(r"[ʿʾʻʼ'`‘’]", "", t)
    k = h % 3
    if k == 0:
        return "latin_lowercase_plain", t.lower()
    if k == 1:
        return "latin_uppercase_plain", t.upper()
    return "latin_hyphens_to_spaces", re.sub(r"\s*-\s*", " ", t)


# --- generation -----------------------------------------------------------------------------

def generate(places, names, log=print) -> list[dict]:
    by_rec = defaultdict(list)
    for n in names:
        by_rec[n["record_id"]].append(n)
    place_by_id = {p["record_id"]: p for p in places}
    # name families over all Arabic names (same-name places are never merged)
    fam = defaultdict(set)
    for n in names:
        if n["is_arabic"] and script_issue(n["name_issue"]) is None and n["name_family_id"]:
            fam[n["name_family_id"]].add(n["record_id"])
        elif n["is_latin"] and n["name_family_id"]:
            fam[n["name_family_id"]].add(n["record_id"])

    def admin_context(p):
        """(Arabic, Latin) context names: parent place, else the deepest resolved admin unit
        above the place, else admin1."""
        for pid in p["parent_place_ids"]:
            q = place_by_id.get(pid)
            if q:
                return q["name_ar"], q["name_en"], "parent_place"
        nodes = [n for n in p["admin_path"][1:] if n["status"] == "resolved" and n["name_ar"]]
        if nodes:
            n = nodes[-1] if len(nodes) <= 2 else nodes[1]
            return n["name_ar"], n["name_en"], f"admin{n['level']}"
        return None, None, None

    cands = defaultdict(lambda: {"shared": [], "unique": []})
    for p in places:
        if p["feature_class"] not in TARGET_CLASSES or p["possible_duplicate_of"]:
            continue
        others = fam.get(p["name_family_id"], set()) - {p["record_id"]}
        cands[p["country_code"]]["shared" if len(others) >= 2 else "unique"].append(p)
    targets = []
    for cc in sorted(cands):
        sh = sorted(cands[cc]["shared"], key=lambda p: _hx(SPLIT_SALT, "t", p["record_id"]))
        un = sorted(cands[cc]["unique"], key=lambda p: _hx(SPLIT_SALT, "t", p["record_id"]))
        n_un = min(len(un), int(MAX_TARGETS_PER_STATE * UNIQUE_SHARE))
        n_sh = min(len(sh), MAX_TARGETS_PER_STATE - n_un)
        targets += sh[:n_sh] + un[:n_un]

    examples = []
    for p in targets:
        rid = p["record_id"]
        rows = by_rec[rid]
        h = _hx(SPLIT_SALT, "k", rid)
        canon = p["name_ar"]
        made = []
        # 1. Arabic: a real variant, an orthographic variant or a typo
        variants = sorted({visible(n["name"]) for n in rows if n["is_arabic"]
                           and script_issue(n["name_issue"]) is None} - {canon})
        ortho = _ortho_variants(canon)
        choice = h % 3
        if choice == 0 and variants:
            made.append(("ar_variant", "source_name", variants[(h >> 4) % len(variants)], "source_annotation"))
        elif choice in (0, 1) and ortho:
            r, v = ortho[(h >> 4) % len(ortho)]
            made.append(("ar_orthographic", r, v, "synthetic_rule"))
        else:
            t = _typo(canon, h >> 4)
            if t:
                made.append(("ar_typo", "one_edit", t, "synthetic_rule"))
            elif ortho:
                r, v = ortho[(h >> 4) % len(ortho)]
                made.append(("ar_orthographic", r, v, "synthetic_rule"))
            elif variants:
                made.append(("ar_variant", "source_name", variants[(h >> 4) % len(variants)], "source_annotation"))
        # 2. Latin: a real romanisation or English name, as given or made messy
        latin = sorted({visible(n["name"]) for n in rows if n["is_latin"]})
        if latin:
            s = latin[(h >> 12) % len(latin)]
            if (h >> 16) % 2 == 0:
                made.append(("latin_variant", "source_name", s, "source_annotation"))
            else:
                r, v = _latin_messy(s, h >> 20)
                if v != s:
                    made.append(("latin_messy", r, v, "synthetic_rule"))
                else:
                    made.append(("latin_variant", "source_name", s, "source_annotation"))
        # 3. Admin-qualified string
        c_ar, c_en, c_kind = admin_context(p)
        if c_ar and ar_match_key(c_ar) != ar_match_key(canon):
            g = GENERIC_AR.get(p["feature_class"], {}).get(p["feature_code"] or "", "")
            base = canon if not g or canon.startswith(g + " ") else f"{g} {canon}"
            sep = ["، ", " - ", ", "][(h >> 24) % 3]
            if (h >> 28) % 2 == 0 or not (c_en and latin):
                made.append(("ar_admin_qualified", f"{c_kind}_context", f"{base}{sep}{c_ar}", "synthetic_rule"))
            else:
                s = p["name_en"] or latin[0]
                suffix = " Dist." if p["feature_code"] == "PPLX" and (h >> 30) % 2 == 0 else ""
                made.append(("latin_admin_qualified", f"{c_kind}_context", f"{s}{suffix}, {c_en}", "synthetic_rule"))
        split = split_of(p)
        hint_all = (h >> 32) % 2 == 0
        for i, (kind, rule, text, origin) in enumerate(made):
            text = re.sub(r"\s+", " ", text).strip()
            if not text:
                continue
            sc = script_of(text.split("،")[0].split(",")[0])
            dis = set(fam.get(p["name_family_id"], set()))
            if sc == "Latn":
                key = latin_match_key(SEP.split(text)[0])
                for n in rows:
                    if n["is_latin"] and n["match_key"] == key and n["name_family_id"]:
                        dis |= fam.get(n["name_family_id"], set())
            dis.discard(rid)
            ordered = sorted(dis, key=lambda d: (place_by_id[d]["country_code"] != p["country_code"],
                                                 _hx(SPLIT_SALT, "d", rid, d)))
            examples.append({
                "example_id": f"me-{_hx(SPLIT_SALT, 'e', rid, i, text):012x}",
                "input": text, "input_script": script_of(text), "input_kind": kind, "rule": rule,
                "target_record_id": rid, "distractor_ids": ordered[:MAX_DISTRACTORS],
                "n_distractors": len(ordered),
                "jurisdiction_hint": p["country_code"] if hint_all else None,
                "label_origin": origin, "split": split,
            })
    examples.sort(key=lambda e: (e["split"], e["example_id"]))
    seen = set()
    out = []
    for e in examples:
        if e["example_id"] in seen:
            continue
        seen.add(e["example_id"])
        out.append(e)
    return out


# --- baseline -------------------------------------------------------------------------------

FCODE_RANK = {"PPLC": 0, "PPLA": 1, "PPLA2": 2, "PPLA3": 3, "PPLA4": 4, "ADM1": 5, "ADM2": 6, "PPL": 7}


class Matcher:
    """Baseline: exact, then normalised exact match, plus admin context.

    Every name of every record is indexed three ways: as written (NFC, spaces collapsed,
    invisible format controls removed); under
    its matching key (Arabic: bayanat-norm-v1 with ة→ه, hamza seats folded and the article
    removed; Latin: folded, articles removed, doubled letters collapsed); and under the matching
    key without a leading generic word (حي، مدينة ... ; district, city ...). An input is split at
    commas, Arabic commas, semicolons and ' - '. The first part is looked up in the three indexes
    in that order, and the first index that returns candidates is used. The other parts are
    matched against the names of each candidate's admin units and parent places. A country hint,
    when given, keeps candidates in that country. Ties go to the larger population, then to
    capitals and admin seats, then to the record with more resolved admin levels, then to the
    lowest record_id. With whole_string=True only the whole input as written is looked up."""

    def __init__(self, places, names, whole_string: bool = False):
        self.whole_string = whole_string
        self.places = {p["record_id"]: p for p in places}
        self.tiers = [defaultdict(set), defaultdict(set), defaultdict(set)]
        names_of = defaultdict(set)
        for n in names:
            if script_issue(n["name_issue"]) in ("not_arabic_script", "arabic_script_in_latin_slot"):
                continue
            for i, k in enumerate(self._keys(n["name"])):
                if k:
                    self.tiers[i][k].add(n["record_id"])
            names_of[n["record_id"]].add(n["name"])
        self.context = {}
        if whole_string:
            return
        for rid, p in self.places.items():
            ctx = set()
            refs = [x["record_id"] for x in p["admin_path"] if x["record_id"]] + list(p["parent_place_ids"])
            for r in refs:
                for nm in names_of.get(r, ()):
                    ctx |= set(self._keys(nm)[1:])
            for x in p["admin_path"]:
                for nm in (x["name_ar"], x["name_en"]):
                    if nm:
                        ctx |= set(self._keys(nm)[1:])
            ctx.discard("")
            self.context[rid] = ctx

    @staticmethod
    def _keys(s: str) -> tuple:
        """(as written, matching key, matching key without a leading generic word)."""
        raw = s = visible(s)
        if script_of(s) == "Arab":
            k = ar_match_key(s)
            return raw, k, ar_core_key(k)
        k = latin_match_key(s)
        words = k.split()
        core = " ".join(w for w in words if w not in LATIN_GENERIC) or k
        return raw, k, core

    def predict(self, text: str, hint: str | None = None) -> str | None:
        if self.whole_string:
            parts, tiers = [text], self.tiers[:1]
        else:
            parts, tiers = [x for x in SEP.split(text) if x.strip()], self.tiers
        if not parts:
            return None
        keys = self._keys(parts[0])
        cands = set()
        for i, index in enumerate(tiers):
            cands = set(index.get(keys[i], ()))
            if hint:
                cands = {c for c in cands if self.places[c]["country_code"] == hint}
            if cands:
                break
        if not cands:
            return None
        if len(parts) > 1 and len(cands) > 1:
            ctx = set()
            for x in parts[1:]:
                ctx |= set(self._keys(x)[1:])
            narrowed = {c for c in cands if self.context[c] & ctx}
            if narrowed:
                cands = narrowed

        def rank(c):
            p = self.places[c]
            return (-(p["population"] or 0), FCODE_RANK.get(p["feature_code"] or "", 9),
                    -(p["admin_levels_resolved"] or 0), c)
        return min(cands, key=rank)


BASELINES = (("exact_string", True), ("normalised_with_admin_context", False))


def evaluate(examples, places, names) -> dict:
    out = {}
    for label, whole in BASELINES:
        m = Matcher(places, names, whole_string=whole)
        tot = Counter()
        ok = Counter()
        for e in examples:
            pred = m.predict(e["input"], e["jurisdiction_hint"])
            for key in (("all", e["split"]), (e["input_kind"], e["split"]), ("all", "all"), (e["input_kind"], "all")):
                tot[key] += 1
                ok[key] += int(pred == e["target_record_id"])
        res = {}
        for (kind, split), n in sorted(tot.items()):
            res.setdefault(split, {})[kind] = {"n": n, "correct": ok[(kind, split)],
                                               "accuracy": round(ok[(kind, split)] / n, 4)}
        out[label] = res
    return out
